import { ObjectId } from 'mongodb';
import Course from './course.js';
import database from '../util/database.js';

export const enum Role {
  unknown = 'unknown',
  admin = 'admin',
  professor = 'professor',
  student = 'student',
  assistant = 'assistant',
}

// Manages application users and preferences
export class User {
  // MongoDB autogenerated identificaiton
  public _id: ObjectId;

  // Creates class attributes using parameter properties
  constructor(public role: Role = Role.unknown,
    public name = 'User',
    public email = '',
    public password = '',
    public uiMode: 'light' | 'dark' = 'light',
    public status: 'active' | 'inactive' | 'deleted' = 'active') {
    this._id = new ObjectId();
    this.email = email.toLowerCase();
  }

  // Create a User object from the given json object
  static factory(jsonObject: User | undefined) {
    const user = new User();
    if (jsonObject) {
      Object.assign(user, jsonObject);
      user._id = new ObjectId(jsonObject._id);
    }
    return user;
  }

  // Getter methods
  isAdmin() { return this.role === Role.admin; }

  isProfessor() { return this.role === Role.professor; }

  isStudent() { return this.role === Role.student; }

  isAssistant() { return this.role === Role.assistant; }

  // Add this user as new one in database
  async save() {
    await database.users().insertOne(this);
  }

  // Updates the database object with this one
  async update() {
    await database.users().updateOne({ _id: new ObjectId(this._id) },
      { $set: this });
  }

  // Find a user in DB by email, returns the found user object
  static async findByEmail(email: string) {
    // Build a query object having email in lowercase
    const query = { email: email.toLowerCase() };
    // Get all users with this email in database
    const users = await database.users().find(query).toArray() as User[];
    // Only one user must have this email (i.e unique key)
    if (users.length > 1) {
      throw new Error(`dberror: several users with email ${email}`);
    }
    // If found return this user. If not-found, array is empty, return undefined
    return users.length === 1 ? User.factory(users[0]) : undefined;
  }

  // Find a user in DB by ID
  static async findById(id: string) {
    // Build a query converting the string to a valid MongoDB ObjectId
    const query = { _id: new ObjectId(id) };
    // Get the user, next() returns a promise to the last object of the results
    const user = await database.users().findOne(query) as User;
    // Return the result. It may be undefined
    return User.factory(user);
  }

  // Delete a user from the database by its id
  static async deleteById(id: string | ObjectId) {
    // Build a query using the identification of the user
    const query = { _id: new ObjectId(id) };
    // Remove from database
    // TODO: Remove a user only if it has no related data (set deleted state and
    // only admins/prof may actually delete accounts and all related data)
    const result = await database.users().deleteOne(query);
    // Return a Result object, with properties such as deletedCount
    return result;
  }

  /**
   * Enrolls this user to the given course. If user is already enrolled, no
   * change is made.
   */
  async enroll(course: Course) {
    await database.users().updateOne({ _id: new ObjectId(this._id) }, {
      $push: { courses: { id: course._id } },
    });
  }
}
